def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def factorize(n):
    """Helper function to factorize a number into its prime factors."""
    factors = []
    if n == 1:
        return factors
    # Handle 2 separately
    while n % 2 == 0:
        factors.append(2)
        n = n // 2
    # Check odd numbers up to sqrt(n)
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n = n // i
        i += 2
    if n > 1:
        factors.append(n)
    return factors

def is_multiply_prime(a):
    """Returns true if the given number is the multiplication of 3 prime numbers and false otherwise."""
    if a < 2:
        return False
    factors = factorize(a)
    # Check if all factors are prime and there are exactly 3 distinct primes (allowing for duplicates)
    distinct_primes = set(factors)
    if len(distinct_primes) != 3:
        return False
    for prime in distinct_primes:
        if not is_prime(prime):
            return False
    return True
