def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    pivot = 0

    # Find the pivot where the order is broken (the point where arr[i] > arr[(i+1)%n])
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            pivot = i + 1
            break

    # Check if the array is already non-decreasing
    if pivot == 0:
        return True

    # Check if the array is non-decreasing after pivot is moved to the front
    for i in range(pivot, n - 1):
        if arr[i] > arr[i + 1]:
            return False

    # Check the wrap-around part (from start to pivot-1)
    if arr[-1] > arr[0]:
        return False

    return True
