import math

def max_fill(grid, capacity):
    """
    Calculate the number of times a bucket needs to be lowered to empty all wells.
    """
    total_water = 0
    for well in grid:
        total_water += sum(well)

    if total_water == 0:
        return 0

    return math.ceil(total_water / capacity)
