    if month < 1 or month > 12:
        return False

    # Check day validity based on month
    if month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False
    else:
        if day < 1 or day > 31:
            return False

    return True
